class Dog:
    """A class is a blueprint."""

    def __init__(self, name):
        self.name = name  # attribute

    def bark(self):
        return f"{self.name} says woof!"  # method


print("class:", Dog)
fido = Dog("Fido")  # object / instance
print("instance:", fido)
print("attribute name:", fido.name)
print("method bark():", fido.bark())

vocab = {
    "class": "blueprint for objects",
    "object/instance": "a concrete value built from a class",
    "attribute": "data hanging off self",
    "method": "function hanging off self",
}
for k, v in vocab.items():
    print(f"- {k}: {v}")
